function studyWord(token:string):Word { const greek=token.replace(/^[«“•❐❍✕✖]+|[.,;·:»”]+$/g,""); const hint=lexicalHints[greek];return withLemma({greek,en:hint?.[1]??"Study in context",ko:hint?.[2]??"문맥에서 확인",lemma:hint?.[0]??greek,grammarEn:"Morphological analysis pending verification",grammarKo:"형태론 분석 검증 예정",meaningEn:hint?.[1]??"Lexical gloss pending verification",meaningKo:hint?.[2]??"어휘 뜻 검증 예정",originEn:"Etymology pending source verification.",originKo:"어원 자료 검증 예정입니다.",usageEn:"Consult the verse-level translation for context; detailed usage notes are in preparation.",usageKo:"문맥은 절별 번역을 참고해 주십시오. 자세한 용법 해설은 준비 중입니다."});}
function speakGreek(value:string, setAudioMessage:(message:string)=>void) {
  if (typeof window==="undefined" || !("speechSynthesis" in window)) {setAudioMessage("This browser does not support speech playback. / 이 브라우저는 음성 재생을 지원하지 않습니다.");return;}
  window.speechSynthesis.cancel();
  const utterance=new SpeechSynthesisUtterance(value);
  utterance.lang="el-GR";utterance.rate=0.85;
  const greekVoice=window.speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith("el"));
  if(greekVoice) utterance.voice=greekVoice;
  else {setAudioMessage("No Greek voice is installed. Playback may use an inaccurate fallback. / 헬라어 음성이 없어 발음이 부정확할 수 있습니다.");}
  window.speechSynthesis.speak(utterance);
}
